package com.ganesh.bookshop.model; import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; @Entity @Table(name="books") public class Book { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String title; @NotBlank private String author; private String category; @NotNull @Positive private BigDecimal price; @Min(0) private Integer stock; public Book(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public Integer getStock(){return stock;} public void setStock(Integer v){stock=v;} }